int shortest_span(const std::vector<int>& values, long long threshold) {
    int n = values.size();
    std::vector<int> dp(n + 1, INT_MAX);
    dp[0] = 0;
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j < i; ++j) {
            if (values[j] + values[i] <= threshold) {
                dp[i] = std::min(dp[i], dp[j] + 1);
            }
        }
    }
    return dp[n];
}

#include <algorithm>
#include <functional>
#include <string>
#include <vector>
#include <unordered_map>

std::vector<std::vector<int>> build_layers(int n, const std::vector<std::pair<int,int>>& prerequisites) {
    std::vector<std::vector<int>> layers;
    std::unordered_map<int, std::vector<int>> graph;
    std::unordered_map<int, int> indegree;

    // Build the graph
    for (const auto& pair : prerequisites) {
        int a = pair.first;
        int b = pair.second;
        graph[a].push_back(b);
        indegree[b]++;
    }

    // Topological sort
    std::queue<int> q;
    for (int i = 0; i < n; ++i) {
        if (indegree[i] == 0) {
            q.push(i);
        }
    }

    while (!q.empty()) {
        int current = q.front();
        q.pop();

        layers.push_back({current});
        for (const auto& neighbor : graph[current]) {
            indegree[neighbor]--;
            if (indegree[neighbor] == 0) {
                q.push(neighbor);
            }
        }
    }

    return layers;
}

#include <algorithm>
#include <functional>
#include <string>
#include <vector>

std::vector<std::string> top_words(const std::vector<std::string>& words, int k) {
    std::sort(words.begin(), words.end());
    std::vector<std::string> result;
    std::unordered_map<std::string, int> word_count;

    for (const auto& word : words) {
        word_count[word]++;
        if (word_count[word] > k) {
            break;
        }
        result.push_back(word);
    }

    return result;
}

